impl SnrMonitor {
    pub fn calculate_score(&self, evidence: &Evidence) -> f64 {
        let base_score = self.compute_base_snr();
        let attestation_bonus = if evidence.has_tpm_quote() { 0.1 } else { 0.0 };
        let trust_decay = self.compute_trust_decay(evidence.age());

        (base_score + attestation_bonus) * (1.0 - trust_decay)
    }
